-- Stores the frozen A7Q_C2 GPT Native packet in unit_metadata and hands it to GPT Native as an operational event
-- (HANDOFF_DEEP_CONTEXT). Data only: no action spec, checkpoint status or assertion changes. C2 stays PENDING.
-- The event carries a pointer to the packet, its hashes and the instructions text; it declares no acceptance.
-- Tier: OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT (not provider-attested).
BEGIN;
DO $a7q_c2_prep$
DECLARE
 v_plan constant text := 'PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1';
 v_unit constant text := 'A7Q';
 v_cp constant text := 'A7Q_C2';
 v_wi constant bigint := 1117;
 v_exec constant text := 'ANALYSIS_QUAL_C2_GPT_HANDOFF_V1|A7Q_C2';
 v_packet_sha constant text := '882465a62c16e70da928ed4530d76717d25389e007144c7069a759131f989753';
 v_packet jsonb := $pkt${"checkpoint":"C2","deterministic_checks":{"forbidden_modes":["REUSE_AS_IS","NOT_APPLICABLE"],"forbidden_solution_patterns":["\\bredis\\b","\\bkafka\\b","\\bpostgres\\w*","\\breact\\b","\\bsql\\b","\\bapi\\b","\\bendpoint\\b","\\btrigger\\b","\\bmigraci\\w+","\\bmicroservic\\w+","\\brpc\\b","\\bedge function\\b","\\btabla\\b","\\bbase de datos\\b","\\bcomponente\\b"],"front_keys":["blockers","closure","evidence_refs","front_id","obligation_mode","reason","scope_ids"],"min_fronts":3,"modes":["REQUIRED","REUSE_AS_IS","NOT_APPLICABLE"],"request_ref_equals":"REQ-LF-A1Q-C2-PILOT-0001"},"evidence_tier":"OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT","input":{"input_literal":"{\n  \"a6_stage_output\": {\n    \"dimensions\": {\n      \"data\": {\n        \"blocked_by\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-004\"\n        ],\n        \"note\": \"Se identifican como conceptos materiales el ahorro y el monto de la cuota. No están autorizadas sus definiciones, valores, bases de comparación ni relaciones. No se presuponen importes ni reglas de cálculo.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\"\n      },\n      \"errors\": {\n        \"blocked_by\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-003\"\n        ],\n        \"note\": \"No se suministran comportamientos autorizados frente a información de ahorro no disponible, indeterminada o incompatible con las condiciones de la oferta. No se establecen resultados de error sin evidencia.\",\n        \"status\": \"BLOCKED_UNDETERMINED\"\n      },\n      \"functional\": {\n        \"blocked_by\": [\n          \"A5-DEC-001\",\n          \"A5-DEC-002\",\n          \"A5-DEC-003\",\n          \"A5-DEC-004\"\n        ],\n        \"note\": \"Se identifican las obligaciones funcionales de comunicar el ahorro antes de aceptar una oferta y distinguirlo de la cuota. Su alcance, significado y condiciones permanecen pendientes de decisión.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\"\n      },\n      \"permissions\": {\n        \"blocked_by\": [\n          \"A5-DEC-001\"\n        ],\n        \"note\": \"La entrada no proporciona evidencia de permisos, roles autorizados ni reglas de acceso. No se establecen permisos por inferencia.\",\n        \"status\": \"BLOCKED_UNDETERMINED\"\n      },\n      \"side_effects\": {\n        \"blocked_by\": [\n          \"A5-DEC-003\",\n          \"A5-DEC-004\"\n        ],\n        \"note\": \"No se conocen efectos colaterales autorizados asociados a comunicar el ahorro, distinguir cuotas o aceptar ofertas. No se afirma que existan ni que estén ausentes.\",\n        \"status\": \"BLOCKED_UNDETERMINED\"\n      },\n      \"state\": {\n        \"blocked_by\": [\n          \"A5-DEC-003\"\n        ],\n        \"note\": \"No existe evidencia suficiente sobre los estados de la oferta, sus transiciones o las condiciones que habilitan comunicar el ahorro. No se inventan estados.\",\n        \"status\": \"BLOCKED_UNDETERMINED\"\n      }\n    },\n    \"evidence_refs\": [\n      \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n      \"supabase://public.lf_eventos/20843\",\n      \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n      \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n      \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n      \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n      \"gap:ACCEPTANCE_EVIDENCE_MISSING\",\n      \"decision:A5-DEC-001\",\n      \"decision:A5-DEC-002\",\n      \"decision:A5-DEC-003\",\n      \"decision:A5-DEC-004\",\n      \"decision:A5-DEC-005\"\n    ],\n    \"no_unlicensed_how\": true,\n    \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n    \"requirements\": [\n      {\n        \"depends_on_decisions\": [\n          \"A5-DEC-001\",\n          \"A5-DEC-003\"\n        ],\n        \"requirement_id\": \"A6-REQ-001\",\n        \"source_ref\": \"decision:A5-DEC-001\",\n        \"statement\": \"Los clientes comprendidos en el alcance autorizado del piloto deberán poder conocer el ahorro asociado a la negociación de su deuda antes de aceptar una oferta, conforme a las condiciones funcionales que se determinen.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\",\n        \"type\": \"FUNCTIONAL\"\n      },\n      {\n        \"depends_on_decisions\": [\n          \"A5-DEC-002\"\n        ],\n        \"requirement_id\": \"A6-REQ-002\",\n        \"source_ref\": \"decision:A5-DEC-002\",\n        \"statement\": \"La información del ahorro deberá corresponder a una definición y una base de comparación autorizadas, todavía pendientes de determinar.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\",\n        \"type\": \"DATA\"\n      },\n      {\n        \"depends_on_decisions\": [\n          \"A5-DEC-003\"\n        ],\n        \"requirement_id\": \"A6-REQ-003\",\n        \"source_ref\": \"decision:A5-DEC-003\",\n        \"statement\": \"La disponibilidad de la información del ahorro deberá respetar el momento y las condiciones autorizadas de la oferta antes de su aceptación.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\",\n        \"type\": \"FUNCTIONAL\"\n      },\n      {\n        \"depends_on_decisions\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-004\"\n        ],\n        \"requirement_id\": \"A6-REQ-004\",\n        \"source_ref\": \"decision:A5-DEC-004\",\n        \"statement\": \"La información comunicada al cliente deberá permitir distinguir el ahorro de la negociación del monto de la cuota, conforme a las definiciones funcionales que resulten autorizadas.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\",\n        \"type\": \"FUNCTIONAL\"\n      },\n      {\n        \"depends_on_decisions\": [\n          \"A5-DEC-004\",\n          \"A5-DEC-005\"\n        ],\n        \"requirement_id\": \"A6-REQ-005\",\n        \"source_ref\": \"decision:A5-DEC-005\",\n        \"statement\": \"La claridad de la información sobre ahorro y cuota deberá poder evaluarse mediante criterios de comprensión y aceptación previamente autorizados para el piloto.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\",\n        \"type\": \"NON_FUNCTIONAL\"\n      }\n    ],\n    \"requirements_statement\": \"Se formularon cinco requisitos provisionales, de naturaleza funcional, de datos y no funcional, vinculados a las cinco decisiones pendientes de A5. Ninguno constituye una obligación aprobada ni una autorización de implementación. Las dimensiones funcional y de datos contienen únicamente necesidades condicionadas. Permisos, estados, errores y efectos colaterales permanecen BLOCKED_UNDETERMINED por falta de evidencia. También están pendientes la verificación de autoridad vigente, la identificación de la implementación existente y la línea base AS-IS. El resultado expresa exclusivamente QUÉ se necesita definir y cumplir, sin seleccionar tecnología, diseño, estructuras internas, reglas económicas no autorizadas ni decisiones de producto.\",\n    \"schema_version\": \"A6_REQUIREMENTS_OUTPUT_V1\"\n  }\n}","input_origin":"A6Q_C2 GPT Native RAW (raw_output_sha256 e6ceef2605a44a7f63837784089cf3c8f40f7a3500d20f2a07adfc63c5cfac29)","input_sha256":"0123c9036da30d1235033b8d3c9ac3507f528ea2b36c2da93b97e5085094971b","request_ref":"REQ-LF-A1Q-C2-PILOT-0001"},"limits":{"checkpoint_transition":false,"db_write":false,"independent_assurance_admitted":false,"provider_attested":false,"real_execution_receipt":false,"transcript_is_provider_evidence":false},"output_contract":{"required_keys":["schema_version","request_ref","material_fronts","evidence_refs","fronts_statement"],"schema":"A7_FRONTS_OUTPUT_V1","validator":"analysis_qualification_a7q_c2_gpt_native_packet_v1.py::semantic_checks"},"owner_approval_doc":"docs/programming-agent/ANALYSIS_C2C3_GPT_NATIVE_APPROVED_EQUIVALENT_V1.md","packet_sha256":"882465a62c16e70da928ed4530d76717d25389e007144c7069a759131f989753","producer_mode":"GPT_NATIVE","profile_source":{"ref":"profiles/programming_analysis_lf/SKILL.md","sha256":"91a7b47c3d84f1d5aea48f3fd475134d9c56c718461d1b649c4a89d53980508f"},"prompt_for_gpt":"Este mensaje es independiente: ignora cualquier otro paquete o salida anterior de este chat. Eres el productor de la etapa A7 (cobertura de frentes) del perfil de análisis. Recibes la salida de la etapa A6 (abajo). Agrupa en frentes materiales todo lo que la entrada obliga a considerar, sin inventar frentes que la entrada no sustente. Cada requisito (requirement_id) y cada dimensión (como 'dimension:<nombre>') de la entrada debe quedar vinculado a al menos un frente. La entrada no trae autoridad positiva ni evidencia de vigencia: por eso NO_APPLICABLE y REUSE_AS_IS están prohibidos, y todo frente queda BLOCKED con bloqueadores que sean decision_id de la entrada. No propongas soluciones técnicas. Referencias válidas: las evidence_refs de la entrada, los requirement_id, 'dimension:<nombre>' y 'decision:<decision_id>'. Devuelve SOLO un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version, request_ref, material_fronts, evidence_refs, fronts_statement. schema_version='A7_FRONTS_OUTPUT_V1'. request_ref='REQ-LF-A1Q-C2-PILOT-0001'. material_fronts: lista de {front_id (único), scope_ids (lista no vacía de requirement_id o 'dimension:<nombre>' de la entrada), obligation_mode (REQUIRED|REUSE_AS_IS|NOT_APPLICABLE), closure (CLOSED|BLOCKED), blockers (lista de decision_id de la entrada), evidence_refs (lista no vacía de referencias válidas), reason (texto)}; al menos 3 frentes. evidence_refs: lista no vacía de referencias válidas. fronts_statement: texto que explica qué frentes quedan bloqueados y por qué.\n\nENTRADA (JSON):\n{\n  \"a6_stage_output\": {\n    \"dimensions\": {\n      \"data\": {\n        \"blocked_by\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-004\"\n        ],\n        \"note\": \"Se identifican como conceptos materiales el ahorro y el monto de la cuota. No están autorizadas sus definiciones, valores, bases de comparación ni relaciones. No se presuponen importes ni reglas de cálculo.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\"\n      },\n      \"errors\": {\n        \"blocked_by\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-003\"\n        ],\n        \"note\": \"No se suministran comportamientos autorizados frente a información de ahorro no disponible, indeterminada o incompatible con las condiciones de la oferta. No se establecen resultados de error sin evidencia.\",\n        \"status\": \"BLOCKED_UNDETERMINED\"\n      },\n      \"functional\": {\n        \"blocked_by\": [\n          \"A5-DEC-001\",\n          \"A5-DEC-002\",\n          \"A5-DEC-003\",\n          \"A5-DEC-004\"\n        ],\n        \"note\": \"Se identifican las obligaciones funcionales de comunicar el ahorro antes de aceptar una oferta y distinguirlo de la cuota. Su alcance, significado y condiciones permanecen pendientes de decisión.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\"\n      },\n      \"permissions\": {\n        \"blocked_by\": [\n          \"A5-DEC-001\"\n        ],\n        \"note\": \"La entrada no proporciona evidencia de permisos, roles autorizados ni reglas de acceso. No se establecen permisos por inferencia.\",\n        \"status\": \"BLOCKED_UNDETERMINED\"\n      },\n      \"side_effects\": {\n        \"blocked_by\": [\n          \"A5-DEC-003\",\n          \"A5-DEC-004\"\n        ],\n        \"note\": \"No se conocen efectos colaterales autorizados asociados a comunicar el ahorro, distinguir cuotas o aceptar ofertas. No se afirma que existan ni que estén ausentes.\",\n        \"status\": \"BLOCKED_UNDETERMINED\"\n      },\n      \"state\": {\n        \"blocked_by\": [\n          \"A5-DEC-003\"\n        ],\n        \"note\": \"No existe evidencia suficiente sobre los estados de la oferta, sus transiciones o las condiciones que habilitan comunicar el ahorro. No se inventan estados.\",\n        \"status\": \"BLOCKED_UNDETERMINED\"\n      }\n    },\n    \"evidence_refs\": [\n      \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n      \"supabase://public.lf_eventos/20843\",\n      \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n      \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n      \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n      \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n      \"gap:ACCEPTANCE_EVIDENCE_MISSING\",\n      \"decision:A5-DEC-001\",\n      \"decision:A5-DEC-002\",\n      \"decision:A5-DEC-003\",\n      \"decision:A5-DEC-004\",\n      \"decision:A5-DEC-005\"\n    ],\n    \"no_unlicensed_how\": true,\n    \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n    \"requirements\": [\n      {\n        \"depends_on_decisions\": [\n          \"A5-DEC-001\",\n          \"A5-DEC-003\"\n        ],\n        \"requirement_id\": \"A6-REQ-001\",\n        \"source_ref\": \"decision:A5-DEC-001\",\n        \"statement\": \"Los clientes comprendidos en el alcance autorizado del piloto deberán poder conocer el ahorro asociado a la negociación de su deuda antes de aceptar una oferta, conforme a las condiciones funcionales que se determinen.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\",\n        \"type\": \"FUNCTIONAL\"\n      },\n      {\n        \"depends_on_decisions\": [\n          \"A5-DEC-002\"\n        ],\n        \"requirement_id\": \"A6-REQ-002\",\n        \"source_ref\": \"decision:A5-DEC-002\",\n        \"statement\": \"La información del ahorro deberá corresponder a una definición y una base de comparación autorizadas, todavía pendientes de determinar.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\",\n        \"type\": \"DATA\"\n      },\n      {\n        \"depends_on_decisions\": [\n          \"A5-DEC-003\"\n        ],\n        \"requirement_id\": \"A6-REQ-003\",\n        \"source_ref\": \"decision:A5-DEC-003\",\n        \"statement\": \"La disponibilidad de la información del ahorro deberá respetar el momento y las condiciones autorizadas de la oferta antes de su aceptación.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\",\n        \"type\": \"FUNCTIONAL\"\n      },\n      {\n        \"depends_on_decisions\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-004\"\n        ],\n        \"requirement_id\": \"A6-REQ-004\",\n        \"source_ref\": \"decision:A5-DEC-004\",\n        \"statement\": \"La información comunicada al cliente deberá permitir distinguir el ahorro de la negociación del monto de la cuota, conforme a las definiciones funcionales que resulten autorizadas.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\",\n        \"type\": \"FUNCTIONAL\"\n      },\n      {\n        \"depends_on_decisions\": [\n          \"A5-DEC-004\",\n          \"A5-DEC-005\"\n        ],\n        \"requirement_id\": \"A6-REQ-005\",\n        \"source_ref\": \"decision:A5-DEC-005\",\n        \"statement\": \"La claridad de la información sobre ahorro y cuota deberá poder evaluarse mediante criterios de comprensión y aceptación previamente autorizados para el piloto.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\",\n        \"type\": \"NON_FUNCTIONAL\"\n      }\n    ],\n    \"requirements_statement\": \"Se formularon cinco requisitos provisionales, de naturaleza funcional, de datos y no funcional, vinculados a las cinco decisiones pendientes de A5. Ninguno constituye una obligación aprobada ni una autorización de implementación. Las dimensiones funcional y de datos contienen únicamente necesidades condicionadas. Permisos, estados, errores y efectos colaterales permanecen BLOCKED_UNDETERMINED por falta de evidencia. También están pendientes la verificación de autoridad vigente, la identificación de la implementación existente y la línea base AS-IS. El resultado expresa exclusivamente QUÉ se necesita definir y cumplir, sin seleccionar tecnología, diseño, estructuras internas, reglas económicas no autorizadas ni decisiones de producto.\",\n    \"schema_version\": \"A6_REQUIREMENTS_OUTPUT_V1\"\n  }\n}","request_sha256":"8caf4b18710abf7232735a49cd9363b46201251e18848c333d62f8341560b880","run_id":"A7Q_C2-GPTN-PILOT-0001","schema":"ANALYSIS_GPT_NATIVE_PACKET_V1","stage_output_selector":"A7","subject_ref":"PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1/A7Q/A7Q_C2","unit":"A7"}$pkt$;
 v_m jsonb; v_before_specs jsonb; v_before_cps text; v_after_cps text; v_stored jsonb; v_id bigint; v_p jsonb;
BEGIN
 IF v_packet->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_packet->>'subject_ref' <> v_plan||'/'||v_unit||'/'||v_cp
  THEN RAISE EXCEPTION 'A7Q_C2_PACKET_IDENTITY'; END IF;
 IF encode(sha256(convert_to(v_packet#>>'{input,input_literal}','UTF8')),'hex') <> v_packet#>>'{input,input_sha256}'
  THEN RAISE EXCEPTION 'A7Q_C2_INPUT_SHA_MISMATCH'; END IF;
 IF (v_packet#>>'{limits,provider_attested}')::boolean IS NOT FALSE OR (v_packet#>>'{limits,real_execution_receipt}')::boolean IS NOT FALSE
  THEN RAISE EXCEPTION 'A7Q_C2_LIMITS_NOT_FALSE'; END IF;
 IF (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_cp) IS DISTINCT FROM 'PENDING'
  THEN RAISE EXCEPTION 'A7Q_C2_NOT_PENDING'; END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_before_cps
  FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi FOR UPDATE;
 IF v_m IS NULL THEN RAISE EXCEPTION 'A7Q_UNIT_NOT_FOUND'; END IF;
 IF v_m#>'{gpt_native_packets_v1,A7Q_C2}' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A7Q_C2,packet_sha256}' <> v_packet_sha
  THEN RAISE EXCEPTION 'A7Q_C2_PACKET_DIFFERENT_ALREADY_STORED'; END IF;
 v_before_specs := v_m->'action_specs_v1';
 UPDATE programacion.engineering_plan_units
    SET unit_metadata = v_m || jsonb_build_object('gpt_native_packets_v1',
        COALESCE(v_m->'gpt_native_packets_v1','{}'::jsonb) || jsonb_build_object('A7Q_C2',v_packet))
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 v_stored := v_m#>'{gpt_native_packets_v1,A7Q_C2}';
 IF v_stored IS DISTINCT FROM v_packet THEN RAISE EXCEPTION 'A7Q_C2_PACKET_READBACK_MISMATCH'; END IF;
 IF v_m->'action_specs_v1' IS DISTINCT FROM v_before_specs THEN RAISE EXCEPTION 'A7Q_C2_SPECS_CHANGED'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.lf_eventos WHERE evento_tipo='HANDOFF_DEEP_CONTEXT' AND created_by_execution_id=v_exec) THEN
  INSERT INTO public.lf_eventos(evento_tipo,entidad_tipo,entidad_codigo,descripcion,severidad,origen,created_by_execution_id,payload)
  VALUES('HANDOFF_DEEP_CONTEXT','PROGRAM_PLAN',v_plan||'.A7Q_C2.GPT_NATIVE_HANDOFF',
   'Frozen A7Q_C2 packet handed to GPT Native for a producer run; no acceptance declared.','INFO','DERIVE_FROM_EXECUTION_ID',v_exec,
   jsonb_build_object(
    'evidence_schema_version','operational-event/v2','execution_id',v_exec,
    'producer','ANALYSIS_QUAL_C2_GPT_HANDOFF_V1',
    'purpose','Hand the frozen A7Q_C2 packet to GPT Native so it can produce the stage output in its own chat.',
    'occurred_at',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'),
    'acceptance_declared',false,
    'subject_ref',v_packet->>'subject_ref','checkpoint',v_cp,'work_item_id',v_wi,
    'packet_location','supabase://programacion.engineering_plan_units/'||v_unit||'#unit_metadata.gpt_native_packets_v1.'||v_cp,
    'packet_sha256',v_packet_sha,'request_sha256',v_packet->>'request_sha256',
    'input_sha256',v_packet#>>'{input,input_sha256}','producer_mode','GPT_NATIVE',
    'evidence_tier',v_packet->>'evidence_tier','provider_attested',false,
    'instructions_for_gpt',v_packet->>'prompt_for_gpt',
    'return_instructions','Reply in the same chat with ONLY the JSON object, unedited. Keep the chat link; the verifier needs the RAW JSON, the chat link and the transcript SHA-256. Do not claim provider attestation.',
    'limits_note','Owner-approved GPT Native in-chat equivalent. Not a provider receipt and not an independent review. The checkpoint stays pending until a captured output is verified.'))
  RETURNING id INTO v_id;
  SELECT payload INTO v_p FROM public.lf_eventos WHERE id=v_id;
  IF v_p->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_p->>'instructions_for_gpt' IS DISTINCT FROM v_packet->>'prompt_for_gpt'
   THEN RAISE EXCEPTION 'A7Q_C2_HANDOFF_READBACK_MISMATCH'; END IF;
 END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_after_cps
  FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 IF v_after_cps IS DISTINCT FROM v_before_cps THEN RAISE EXCEPTION 'A7Q_C2_CHECKPOINTS_CHANGED'; END IF;
END
$a7q_c2_prep$;
COMMIT;
